WITH fixtures(name,route,stream,booking) AS (VALUES ('same-id','c64e353d-130e-5390-b916-285b358faac2'::uuid,'82ad0dea-e101-5280-8007-e78ce026aede'::uuid,'b6075b24-e7d6-5e22-9106-76f2cdfc4806'::uuid),('competing','dff0b850-9522-51ee-ba7b-769e14c290b7'::uuid,'a33121dc-d06e-5a4f-95ef-3403ffe599b6'::uuid,'e7bc4faa-02dd-5aa4-b5c4-b2e67a4db4a1'::uuid),('rollback','661045b2-ce79-5c7e-9bd3-4ac6adcc186d'::uuid,'161f33aa-483a-537b-a3dd-19f65f64d65f'::uuid,'741eaf34-60d0-5196-9a0a-39134e19553d'::uuid),('timeout','887f7e0c-b644-556f-99f8-d9c45038e39a'::uuid,'f29b56e5-96dc-52d0-a7b6-cb572dac711a'::uuid,'adf8bffa-0084-5ebf-91af-54e4972ebc82'::uuid),('audit','343ac50d-fad5-59a0-838a-b8616b4c5adb'::uuid,'aa10e3cf-eb0d-5d60-9788-abb2683fde48'::uuid,'7ec055b0-dffa-5d5d-96b3-5fc7bc465544'::uuid),('http','e1d53e64-6d26-5097-b74b-00a7d66dede4'::uuid,'3d36abc8-c9dd-57dc-a724-b1e99f2bb2fd'::uuid,'5a3d5a5f-59aa-5451-b0b8-602c887cf99f'::uuid))
SELECT jsonb_build_object('cases',jsonb_agg(jsonb_build_object('name',f.name,'enabled',s.enabled,'eventCount',s.event_count,'status',b.status,'currentProposal',b.current_proposal_event_id,'auditRows',(SELECT count(*) FROM master_wok_event_test.staff_commands a WHERE a.route_id=f.route),'bookingCommands',(SELECT count(*) FROM master_wok_event_test.booking_commands c WHERE c.stream_id=f.stream),'holds',(SELECT count(*) FROM master_wok_event_test.reservations r WHERE r.stream_id=f.stream),'batch',master_wok_event_test.export(f.stream)) ORDER BY f.name),'enabledStreamsGlobally',(SELECT count(*) FROM master_wok_event_test.streams WHERE enabled),'writerSessions',(SELECT count(*) FROM pg_stat_activity WHERE usename='master_wok_event_writer_login'),'orphanAuditRows',(SELECT count(*) FROM master_wok_event_test.staff_commands a LEFT JOIN master_wok_event_test.events e ON e.stream_id=a.stream_id AND e.sequence=a.event_sequence WHERE e.event_id IS DISTINCT FROM a.command_id::text)) AS verification
FROM fixtures f JOIN master_wok_event_test.streams s ON s.id=f.stream JOIN master_wok_event_test.booking_rows b ON b.stream_id=f.stream AND b.id=f.booking;
